:where([data-gl-theme="beauty-star"]) :is(.product-container,.nad-content,.latky-modal-box,.latky,.story-block-text,.cta-text,.gl-faq,.faq-section,.maly-popis){color:var(--gl-dark-text);}
:where([data-gl-theme="beauty-star"]) :is(.cta-button,.nad-btn,.btn-s,.latky-plus){color:var(--gl-dark-on-accent)!important;}
:where([data-gl-theme="beauty-star"]) :is(.latky-modal-close,.gl-mobile-toggle){border:1px solid var(--gl-dark-border);}
:where([data-gl-theme="beauty-star"]) :is(a,button,summary,[tabindex]):focus-visible{outline:3px solid var(--gl-color-primary);outline-offset:3px;box-shadow:0 0 0 3px var(--gl-dark-bg),0 0 0 6px var(--gl-color-primary);}
:where([data-gl-theme="beauty-star"]) :is(.cta-availability,.cta-status,.gl-cart-message){color:var(--gl-dark-muted);}
:where([data-gl-theme="beauty-star"]) :is(.gl-error,.is-error,[role="alert"]){color:#ffc2c6;}
:where([data-gl-theme="beauty-star"]) :is(.cta-product-img,.nad-mol){background-color:#f5f1f4;border-radius:12px;}
:where([data-gl-theme="beauty-star"]) :is(.gl-draft-note,.doza-safety){color:var(--gl-dark-text);}
:where([data-gl-theme="beauty-star"]) .nad-banner{background-image:linear-gradient(135deg,var(--gl-dark-surface),var(--gl-dark-raised))!important;color:var(--gl-dark-text);}
:where([data-gl-theme="beauty-star"]) .hero-img{background:linear-gradient(145deg,var(--gl-dark-surface),var(--gl-dark-raised))!important;}
:where([data-gl-theme="beauty-star"]) .p-icon-card{background:var(--gl-dark-raised)!important;border-color:var(--gl-dark-border);}
:where([data-gl-theme="beauty-star"]) .cta-box{background:var(--gl-dark-surface)!important;}
:where([data-gl-theme="beauty-star"]) .nad-title{color:var(--gl-color-primary)!important;}
:where([data-gl-theme="beauty-star"]) :is(.nad-dose-sub,.nad-dose-label,.nad-feature,.nad-tagline,.nad-info p){color:var(--gl-dark-text)!important;}
:where([data-gl-theme="beauty-star"]) :is(th){background-color:var(--gl-color-primary)!important;color:var(--gl-dark-on-accent)!important;}
:where([data-gl-theme="beauty-star"]) :is(.cta-button,.nad-btn,.btn-s,.latky-plus){background:var(--gl-color-primary)!important;color:var(--gl-dark-on-accent)!important;}
:where([data-gl-theme="beauty-star"]) .gl-history{background:#332a21!important;color:var(--gl-dark-text);}
:where([data-gl-theme="beauty-star"]) .gl-history :is(p,span,div,summary){color:var(--gl-dark-text)!important;}
:is(#special-popis,#nad-popis)[data-gl-theme="beauty-star"] .gl-mobile-toggle{background:var(--gl-dark-surface)!important;color:var(--gl-color-primary)!important;border-color:var(--gl-dark-border)!important;}
}
/* GOLDIE SYSTEM DARK END */

